-- EXPLAIN ANALYZE runs its statement as PostgreSQL 18's ExplainOnePlan does,
-- so a statement calling a PL/pgSQL function runs it, raises its notices
-- and counts each plan node once. A write whose condition calls a routine
-- qualifies each row in its change loop; its scan's figures count the rows
-- the condition kept and removed. ModifyTable returns its RETURNING rows.
CREATE TABLE t528 (a int, b int);
INSERT INTO t528 SELECT g, g FROM generate_series(1, 5) g;
CREATE TABLE u528 (a int, c text);
INSERT INTO u528 SELECT g, 'x' || g FROM generate_series(1, 3) g;
CREATE FUNCTION pf528(x int) RETURNS int LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE 'pf528 %', x;
  RETURN x + 1;
END
$$;
CREATE FUNCTION count528() RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE
  n bigint;
BEGIN
  SELECT count(*) INTO n FROM u528;
  RETURN n;
END
$$;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT pf528(a) FROM t528;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT a FROM t528 WHERE pf528(a) > 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT pf528(1);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT count(pf528(a)) FROM t528;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM t528 WHERE a = count528();
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  SELECT pf528(a) FROM t528 UNION ALL SELECT pf528(a) FROM u528;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) UPDATE t528 SET b = pf528(b) WHERE a < 3;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) INSERT INTO t528 VALUES (pf528(10), 1);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) INSERT INTO t528 VALUES (6, 6) RETURNING a;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM t528 WHERE pf528(a) = 11;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM t528 WHERE pf528(a) > 6 RETURNING a;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) UPDATE t528 SET b = count528() WHERE pf528(a) = 2;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) UPDATE t528 SET b = 0 WHERE a > 2 RETURNING a, b;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) INSERT INTO u528 SELECT pf528(a), 'y' FROM t528;
ROLLBACK;
SELECT * FROM t528 ORDER BY a;
